function pkScen(){const P=sv.pakd;let c=P.scenarios.find(x=>x.id===(pk&&pk.id))||P.scenarios.find(x=>x.id===P.current)||P.scenarios[0];
 if(!pk||pk.id!==c.id)pk={id:c.id,name:c.name,basis:JSON.parse(JSON.stringify(c.basis||{})),lines:JSON.parse(JSON.stringify(c.lines||[])),parts:JSON.parse(JSON.stringify(c.parts||{})),cf:c.cashflow_inputs?JSON.parse(JSON.stringify(c.cashflow_inputs)):null};return c;}
