 const gr=groups.map(x=>`<tr><td>${esc(x.code)} ${esc(x.name)}<details><summary>${x.bb_codes.length} dòng — gán riêng từng dòng</summary>${x.bb_codes.map(c=>`<label class="inline">${esc(c)} <select data-pln="${esc(g.id)}|${esc(c)}">${opt(sel,plan.by_line[c]||'','theo nhóm')}</select></label>`).join('<br>')}</details></td><td class="num">${money(x.value)}</td><td><select data-pg="${esc(g.id)}|${esc(x.code)}">${opt(sel,plan.by_group[x.code]||'main','Phần chung')}</select></td></tr>`).join('');
