const TERMS=[['advance_pct','Tạm ứng %'],['advance_period','Kỳ tạm ứng'],['recovery_pct','Thu hồi % mỗi kỳ'],['retention_pct','Giữ lại %'],['retention_release','Kỳ hoàn giữ lại'],['delay','Chậm thanh toán (kỳ)'],['ref','Căn cứ']];
function vCash(c){const P=sv.pakd,cf=pk.cf,R=c.cashflow;
 if(!cf)return `<h3>Dòng tiền (FR22)</h3><div class="toolbar"><button id="cf-start">Lập dòng tiền cho kịch bản</button><span class="help">Phân kỳ thu/chi theo lịch nghiệm thu và điều khoản thanh toán; tách khỏi lợi nhuận.</span></div>`;
 const n=Math.max(0,Math.min(120,parseInt(cf.periods)||0));for(const k of ['revenue_pct','ntp_pct','own_pct']){cf[k]=(cf[k]||[]).slice(0,n);while(cf[k].length<n)cf[k].push('');}
 const lbl=i=>{if(!/^\d{4}-\d{2}$/.test(cf.start||''))return 'T'+i;const m=+cf.start.slice(5)-1+i-1;return `${+cf.start.slice(0,4)+Math.floor(m/12)}-${String(m%12+1).padStart(2,'0')}`;};
 const sch=n?`<div class="table-wrap"><table><thead><tr><th>Lịch (% theo kỳ)</th>${Array.from({length:n},(_,i)=>`<th>${esc(lbl(i+1))}</th>`).join('')}<th class="num">Tổng</th></tr></thead><tbody>${[['revenue_pct','Nghiệm thu AB'],['ntp_pct','Nghiệm thu NTP'],['own_pct','Chi phí CC1']].map(([k,l])=>`<tr><td>${l}</td>${cf[k].map((v,i)=>`<td><input class="w-xs" data-cfs="${k}|${i}" value="${esc(v??'')}" inputmode="decimal" aria-label="${l} kỳ ${i+1}"></td>`).join('')}<td class="num">${num(cf[k].reduce((a,v)=>a+(parseFloat(v)||0),0))}</td></tr>`).join('')}</tbody></table></div><div class="toolbar"><button id="cf-copy" class="quiet">Chép lịch AB sang NTP và CC1</button></div>`:'';
 const term=(side,l,keys)=>`<tr><td>${l}</td>${TERMS.map(([k,n])=>`<td>${keys.includes(k)?`<input data-cft="${side}|${k}" value="${esc((cf[side]||{})[k]??'')}" class="${k==='ref'?'':'w-s'}" aria-label="${l} ${n}">`:'—'}</td>`).join('')}</tr>`;
 const all=TERMS.map(x=>x[0]);
 let out=`<h3>Dòng tiền (FR22) — nháp</h3><div class="toolbar"><label>Số kỳ (tháng) <input id="cf-n" class="w-s" value="${esc(cf.periods??'')}" inputmode="numeric"></label><label>Tháng bắt đầu <input id="cf-start-m" class="w-s" value="${esc(cf.start||'')}" placeholder="Kỳ (vd 2026-10)"></label><label>Căn cứ lịch <input id="cf-sref" value="${esc(cf.schedule_ref||'')}" placeholder="Tiến độ thi công / kế hoạch nghiệm thu"></label><button id="cf-drop" class="quiet">Bỏ dòng tiền</button></div>${sch}
 <div class="table-wrap"><table><thead><tr><th>Điều khoản</th>${TERMS.map(x=>`<th>${x[1]}</th>`).join('')}</tr></thead><tbody>${term('ab','HĐ AB (thu)',all)}${term('ntp','HĐ NTP (chi)',all)}${term('own','Chi phí CC1',['delay','ref'])}</tbody></table></div>
 <div class="toolbar"><label>Lãi suất vốn %/năm <input id="cf-rate" class="w-s" value="${esc(cf.rate_pct??'')}" inputmode="decimal"></label><label>Căn cứ lãi suất <input id="cf-rref" value="${esc(cf.rate_ref||'')}"></label><span class="help">Sửa xong bấm "Lưu kịch bản" để tính.</span></div>`;
 if(R&&R.periods.length){const t=R.totals;out+=`<div class="metric-row m4"><div class="metric">Tổng thu<strong>${num(t.in)}</strong></div><div class="metric">Tổng chi<strong>${num(t.out)}</strong></div><div class="metric">Nhu cầu vốn đỉnh<strong>${num(t.peak_funding)}</strong><small>${esc(t.peak_period||'—')}</small></div><div class="metric">Chi phí tài chính ước tính<strong>${t.financing==null?'<span class="chip-block">chưa có lãi suất</span>':num(t.financing)}</strong><small>đối chiếu C.3, không tự cộng</small></div></div>
  <div class="table-wrap"><table><thead><tr><th>Kỳ</th><th class="num">Nghiệm thu AB</th><th class="num">Thu CĐT</th><th class="num">Chi NTP</th><th class="num">Chi CC1</th><th class="num">Ròng</th><th class="num">Lũy kế</th></tr></thead><tbody>${R.periods.map(r=>`<tr><td>${esc(r.label)}</td>${['earned','ab_in','ntp_out','own_out','net','cum'].map(k=>`<td class="num">${num(r[k])}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
 if(R)out+=`${(R.warnings||[]).map(w=>`<div class="question validation-question">${esc(w)}</div>`).join('')}${R.missing.length?`<details class="editor"><summary>Dòng tiền còn thiếu (${R.missing.length})</summary>${R.missing.map(m=>`<div class="question validation-question">${esc(m)}</div>`).join('')}</details>`:''}<p class="help">${esc(R.not_modelled)}</p>`;
 return out;}
