function vExport(){return `<div class="metric-row"><div class="metric">Phòng Đấu thầu<strong>Hồ sơ lập dự toán</strong><small><a href="/api/projects/${project.id}/tender-pack.zip">Tải ZIP</a></small></div><div class="metric">Phòng Chào thầu<strong>Chọn thầu · giao thầu · giá giao</strong><small>${sv.packages.length?`<a href="/api/projects/${project.id}/procurement-pack.zip">Tải ZIP</a>`:'cần gói thầu'}</small></div><div class="metric">Từ điển mã<strong>WBS · CBS · LBS · …</strong><small><a href="/api/dictionaries.xlsx?project=${project.id}">Tải Excel</a></small></div></div>
 <p class="help">Mọi file ghi DỰ THẢO TRÊN MÁY, có bảng kê MANIFEST kèm mã băm SHA-256; bước chưa xác nhận vẫn xuất được nhưng ghi rõ việc còn mở. Không phải hồ sơ phát hành chính thức.</p>
 <h3>Danh mục hồ sơ theo mô hình ${esc(sv.models[sv.pm_model]?.name||'(chưa chọn)')}</h3><div class="table-wrap"><table><thead><tr><th>Mã</th><th>Giai đoạn</th><th>Hồ sơ</th><th>Trạng thái</th></tr></thead><tbody>${(sv.checklist||[]).map(c=>`<tr><td>${esc(c.code)}</td><td>${esc(c.stage)}</td><td>${esc(c.name)}</td><td>${c.state==='DONE'?'<span class="chip-ok">Đủ</span>':'<span class="chip-block">Thiếu</span>'}</td></tr>`).join('')||'<tr><td colspan="4">Chọn mô hình QLDA để xem danh mục hồ sơ.</td></tr>'}</tbody></table></div>`;}
