 const b=(id,fn)=>{const el=q(id);if(el)el.onclick=fn;};
 b('#sh-add',()=>{p.delivery=p.delivery||{};(p.delivery.shared=p.delivery.shared||[]).push({});draw();});
 b('#np-add',()=>{const code=q('#np-code').value.trim(),name=q('#np-name').value.trim();if(!/^GT-\d{2,3}$/.test(code))return say('Mã gói theo mẫu GT-01.',true);if(pkgs().some(x=>x.code===code))return say('Mã gói đã có.',true);const id=crypto.randomUUID();draft.push({id,code,name,lines:[],delivery:{},pricing:{}});cur=id;draw();say('Đã thêm vào bản nháp — bấm Lưu gói thầu.');});
